E=Path(__file__).parent;read=lambda n:json.loads((E/n).read_text());old=read('api-015-restart.json')['result'];new=read('api-015-history-restart.json')['result'];before=next(x for x in read('api-015-captured-own-pids.json')['captures'] if x['phase']=='before-normal-restart');current={int(x.split()[0]) for x in subprocess.check_output(['ps','-axo','pid='],text=True).splitlines() if x.strip()};ids=[x['pid'] for x in before['current']];assert not set(ids)&current,(set(ids)&current);assert new['pid'] in current and old['pid']!=new['pid'];assert all(old[k]==new[k] for k in ['instanceId','dataRoot','databaseUrl','backendUrl','graphqlUrl','controlEndpoint','executablePath']);inspect=read('api-015-inspector-owner.json')['backend']['pid'];assert inspect not in current;out={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'instanceId':new['instanceId'],'sameOwnedProfilePortsExecutable':True,'oldAppPid':old['pid'],'newAppPid':new['pid'],'oldCapturedPids':ids,'allOldCapturedPidsGone':True,'oldInspectorBackendGone':inspect,'scope':'Actual normal whole-app shutdown/restart after observed quiescence. Not browser reload, mid-turn crash recovery, prior failed-generation repair or Task release proof.'};(E/'api-015-whole-app-restart-proof.json').write_text(json.dumps(out,indent=2)+'\n');print('Scoped Pass actual SAME instance profile/ports with new desktop PID and all',len(ids),'captured old desktop/provider descendant PIDs gone; old inspector backend gone')
